-- Member erasure (launch plan 5.7, docs/engineering/member-erasure.md).
--
-- GENERATED by the erasure design's delete-order analysis; the delete list is
-- every table keyed to the membership that the owner chose to delete, plus the
-- rows that hang off them, in foreign-key order (children first). The
-- membership itself stays as an anonymised tombstone.
--
-- These functions run as atlas_platform (SECURITY DEFINER, owner set below),
-- whose policies see every academy, so every statement filters by tenant.
-- atlas_app may call them, but app.erase_member() only acts on a deletion
-- request for that member that is due (scheduled_at has passed): the request,
-- made by the learner or an admin, is the authorisation.

CREATE OR REPLACE FUNCTION app.erase_member(
  p_tenant_id uuid,
  p_membership_id uuid,
  p_deletion_request_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public, app, pg_temp
AS $$
DECLARE
  request_status text;
  principal uuid;
  principal_email text;
  profile_id uuid;
  erasure public.member_erasures%ROWTYPE;
  pending jsonb := '[]'::jsonb;
  deleted jsonb := '{}'::jsonb;
  n bigint;
  redacted_audit bigint := 0;
  redacted_events bigint := 0;
BEGIN
  SELECT dr.status::text INTO request_status
  FROM public.deletion_requests dr
  WHERE dr.id = p_deletion_request_id
    AND dr.tenant_id = p_tenant_id
    AND dr.target_type = 'membership'
    AND dr.target_id = p_membership_id::text
    AND dr.scheduled_at IS NOT NULL
    AND dr.scheduled_at <= now()
  FOR UPDATE;
  IF request_status IS NULL OR request_status NOT IN ('QUEUED', 'RUNNING') THEN
    RAISE EXCEPTION 'no due deletion request % for membership %', p_deletion_request_id, p_membership_id
      USING ERRCODE = 'P0002';
  END IF;

  -- Already erased: the database part is done; report what it recorded.
  SELECT * INTO erasure FROM public.member_erasures
  WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  IF FOUND AND erasure.database_completed_at IS NOT NULL THEN
    RETURN jsonb_build_object(
      'erasureId', erasure.id,
      'principalId', erasure.principal_id,
      'pendingObjects', erasure.pending_objects,
      'alreadyErased', true
    );
  END IF;

  SELECT m.auth_principal_id INTO principal
  FROM public.memberships m
  WHERE m.tenant_id = p_tenant_id AND m.id = p_membership_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'membership % not found', p_membership_id USING ERRCODE = 'P0002';
  END IF;

  -- The academy's owner can't be erased while they own it: ownership moves first.
  IF EXISTS (
    SELECT 1 FROM public.user_roles ur JOIN public.roles r ON r.id = ur.role_id
    WHERE ur.tenant_id = p_tenant_id AND ur.membership_id = p_membership_id AND r.key = 'owner'
  ) THEN
    RAISE EXCEPTION 'the academy owner can''t be erased; transfer ownership first'
      USING ERRCODE = 'P0001';
  END IF;

  IF principal IS NOT NULL THEN
    SELECT ap.email_normalized INTO principal_email FROM public.auth_principals ap WHERE ap.id = principal;
  END IF;
  SELECT mp.id INTO profile_id FROM public.member_profiles mp
  WHERE mp.tenant_id = p_tenant_id AND mp.membership_id = p_membership_id;

  -- Opens the erasure: from here to the end of this transaction,
  -- app.reject_update_delete() lets this academy's append-only rows be
  -- deleted and audit and outbox payloads be redacted.
  INSERT INTO public.member_erasures (tenant_id, membership_id, deletion_request_id, principal_id, txid)
  VALUES (p_tenant_id, p_membership_id, p_deletion_request_id, principal, txid_current())
  RETURNING * INTO erasure;

  -- Files to delete from storage once this commits.
  SELECT coalesce(jsonb_agg(jsonb_build_object('bucket', sr.bucket, 'key', sr.object_key)), '[]'::jsonb)
  INTO pending
  FROM public.storage_references sr
  WHERE sr.tenant_id = p_tenant_id
    AND sr.purpose = 'member.avatar'
    AND sr.resource_type = 'member_profile'
    AND sr.resource_id = p_membership_id;
  SELECT pending || coalesce(jsonb_agg(jsonb_build_object('bucket', NULL, 'key', pma.r2_object_key)), '[]'::jsonb)
  INTO pending
  FROM public.proctoring_media_artifacts pma
  WHERE pma.tenant_id = p_tenant_id
    AND pma.r2_object_key IS NOT NULL
    AND pma.proctoring_session_id IN (
      SELECT id FROM public.proctoring_sessions WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id);

  DELETE FROM public.at_risk_alerts WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('at_risk_alerts', n); END IF;

  DELETE FROM public.attempt_answers WHERE tenant_id = p_tenant_id AND attempt_id IN (
      SELECT id FROM public.attempts WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id);
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('attempt_answers', n); END IF;

  DELETE FROM public.attribution_tokens WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('attribution_tokens', n); END IF;

  DELETE FROM public.badge_awards WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('badge_awards', n); END IF;

  DELETE FROM public.batch_memberships WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('batch_memberships', n); END IF;

  DELETE FROM public.bundle_enrollments WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('bundle_enrollments', n); END IF;

  DELETE FROM public.competency_score_snapshots WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('competency_score_snapshots', n); END IF;

  DELETE FROM public.competency_scores WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('competency_scores', n); END IF;

  DELETE FROM public.competency_signals WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('competency_signals', n); END IF;

  DELETE FROM public.composite_readiness_state WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('composite_readiness_state', n); END IF;

  DELETE FROM public.custom_field_value_history WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('custom_field_value_history', n); END IF;

  DELETE FROM public.custom_field_values WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('custom_field_values', n); END IF;

  DELETE FROM public.device_security_alerts WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('device_security_alerts', n); END IF;

  DELETE FROM public.device_sessions WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('device_sessions', n); END IF;

  DELETE FROM public.diagnostic_sessions WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('diagnostic_sessions', n); END IF;

  DELETE FROM public.enrollments WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('enrollments', n); END IF;

  DELETE FROM public.gamification_profiles WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('gamification_profiles', n); END IF;

  DELETE FROM public.grading_tasks WHERE tenant_id = p_tenant_id AND attempt_id IN (
      SELECT id FROM public.attempts WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id);
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('grading_tasks', n); END IF;

  DELETE FROM public.group_memberships WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('group_memberships', n); END IF;

  DELETE FROM public.identity_verifications WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('identity_verifications', n); END IF;

  DELETE FROM public.learner_subscription_enrollments WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('learner_subscription_enrollments', n); END IF;

  DELETE FROM public.lesson_progress WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('lesson_progress', n); END IF;

  DELETE FROM public.live_attendance WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('live_attendance', n); END IF;

  DELETE FROM public.marketing_event_registrations WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('marketing_event_registrations', n); END IF;

  DELETE FROM public.marketing_newsfeed_saves WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('marketing_newsfeed_saves', n); END IF;

  DELETE FROM public.marketing_workflow_run_logs WHERE tenant_id = p_tenant_id AND run_id IN (
      SELECT id FROM public.marketing_workflow_runs WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id);
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('marketing_workflow_run_logs', n); END IF;

  DELETE FROM public.member_balances WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('member_balances', n); END IF;

  DELETE FROM public.member_notification_preferences WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('member_notification_preferences', n); END IF;

  DELETE FROM public.mock_test_enrollments WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('mock_test_enrollments', n); END IF;

  DELETE FROM public.module_scorm_progress WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('module_scorm_progress', n); END IF;

  DELETE FROM public.notification_dispatches WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('notification_dispatches', n); END IF;

  DELETE FROM public.path_enrollments WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('path_enrollments', n); END IF;

  DELETE FROM public.path_step_progress WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('path_step_progress', n); END IF;

  DELETE FROM public.permission_overrides WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('permission_overrides', n); END IF;

  DELETE FROM public.point_ledger WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('point_ledger', n); END IF;

  DELETE FROM public.poll_responses WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('poll_responses', n); END IF;

  DELETE FROM public.practice_responses WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('practice_responses', n); END IF;

  DELETE FROM public.proctoring_media_artifacts WHERE tenant_id = p_tenant_id AND proctoring_session_id IN (
      SELECT id FROM public.proctoring_sessions WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id);
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('proctoring_media_artifacts', n); END IF;

  DELETE FROM public.proctoring_reports WHERE tenant_id = p_tenant_id AND proctoring_session_id IN (
      SELECT id FROM public.proctoring_sessions WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id);
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('proctoring_reports', n); END IF;

  DELETE FROM public.quest_progress WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('quest_progress', n); END IF;

  DELETE FROM public.reactions WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('reactions', n); END IF;

  DELETE FROM public.reward_redemptions WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('reward_redemptions', n); END IF;

  DELETE FROM public.sales_attribution_events WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('sales_attribution_events', n); END IF;

  DELETE FROM public.srs_state WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('srs_state', n); END IF;

  DELETE FROM public.streak_freezes WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('streak_freezes', n); END IF;

  DELETE FROM public.streak_states WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('streak_states', n); END IF;

  DELETE FROM public.tenant_active_days WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('tenant_active_days', n); END IF;

  DELETE FROM public.test_series_enrollments WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('test_series_enrollments', n); END IF;

  DELETE FROM public.test_series_item_progress WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('test_series_item_progress', n); END IF;

  DELETE FROM public.user_roles WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('user_roles', n); END IF;

  DELETE FROM public.whatsapp_inbox_messages WHERE tenant_id = p_tenant_id AND conversation_id IN (
      SELECT id FROM public.whatsapp_conversations WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id);
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('whatsapp_inbox_messages', n); END IF;

  DELETE FROM public.zoom_meeting_participants WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('zoom_meeting_participants', n); END IF;

  DELETE FROM public.marketing_workflow_runs WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('marketing_workflow_runs', n); END IF;

  DELETE FROM public.practice_sessions WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('practice_sessions', n); END IF;

  DELETE FROM public.proctoring_events WHERE tenant_id = p_tenant_id AND proctoring_session_id IN (
      SELECT id FROM public.proctoring_sessions WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id);
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('proctoring_events', n); END IF;

  DELETE FROM public.whatsapp_conversations WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('whatsapp_conversations', n); END IF;

  DELETE FROM public.proctoring_sessions WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('proctoring_sessions', n); END IF;

  DELETE FROM public.attempts WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('attempts', n); END IF;

  DELETE FROM public.storage_references
  WHERE tenant_id = p_tenant_id
    AND purpose = 'member.avatar'
    AND resource_type = 'member_profile'
    AND resource_id = p_membership_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('storage_references', n); END IF;

  DELETE FROM public.analytics_rollups
  WHERE tenant_id = p_tenant_id AND subject_id = p_membership_id::text;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN deleted := deleted || jsonb_build_object('analytics_rollups', n); END IF;

  -- Marketing contacts made from their email, and what hangs off them.
  IF principal_email IS NOT NULL THEN
    DELETE FROM public.marketing_event_registrations
    WHERE tenant_id = p_tenant_id AND contact_id IN (
      SELECT id FROM public.marketing_contacts WHERE tenant_id = p_tenant_id AND lower(email) = principal_email);
    DELETE FROM public.marketing_form_submissions
    WHERE tenant_id = p_tenant_id AND contact_id IN (
      SELECT id FROM public.marketing_contacts WHERE tenant_id = p_tenant_id AND lower(email) = principal_email);
    DELETE FROM public.marketing_contacts WHERE tenant_id = p_tenant_id AND lower(email) = principal_email;
    GET DIAGNOSTICS n = ROW_COUNT;
    IF n > 0 THEN deleted := deleted || jsonb_build_object('marketing_contacts', n); END IF;
  END IF;

  -- The profile shows as "Deleted member" wherever kept records name it.
  UPDATE public.member_profiles
  SET display_name = 'Deleted member',
      avatar_key = NULL,
      bio = NULL,
      metadata_json = '{}'::jsonb,
      timezone = NULL,
      profile_visibility = 'PRIVATE',
      updated_at = now()
  WHERE tenant_id = p_tenant_id AND membership_id = p_membership_id;

  -- The tombstone: no login, no invitation, no way back in.
  UPDATE public.memberships
  SET status = 'REMOVED',
      removed_at = coalesce(removed_at, now()),
      erased_at = now(),
      auth_principal_id = NULL,
      invited_email_normalized = NULL,
      invite_token_hash = NULL,
      invite_expires_at = NULL,
      last_active_at = NULL,
      updated_at = now()
  WHERE tenant_id = p_tenant_id AND id = p_membership_id;

  -- Audit entries about or by them keep their IDs; payloads are redacted
  -- (the trigger records the original hashes for the chain).
  UPDATE public.audit_entries
  SET before_json = CASE WHEN before_json IS NULL THEN NULL ELSE '{"redacted": true}'::jsonb END,
      after_json = CASE WHEN after_json IS NULL THEN NULL ELSE '{"redacted": true}'::jsonb END,
      metadata_json = CASE WHEN metadata_json IS NULL THEN NULL ELSE '{"redacted": true}'::jsonb END
  WHERE tenant_id = p_tenant_id
    AND (
      actor_membership_id = p_membership_id
      OR (principal IS NOT NULL AND actor_principal_id = principal)
      OR target_id = p_membership_id::text
      OR (principal IS NOT NULL AND target_id = principal::text)
      OR (profile_id IS NOT NULL AND target_id = profile_id::text)
    )
    AND (
      before_json IS DISTINCT FROM '{"redacted": true}'::jsonb
      OR after_json IS DISTINCT FROM '{"redacted": true}'::jsonb
      OR metadata_json IS DISTINCT FROM '{"redacted": true}'::jsonb
    )
    AND (before_json IS NOT NULL OR after_json IS NOT NULL OR metadata_json IS NOT NULL);
  GET DIAGNOSTICS redacted_audit = ROW_COUNT;

  -- Events about them, delivered or not, carry no personal data afterwards.
  UPDATE public.outbox_events
  SET payload_json = '{"redacted": true}'::jsonb,
      metadata_json = CASE WHEN metadata_json IS NULL THEN NULL ELSE '{"redacted": true}'::jsonb END
  WHERE tenant_id = p_tenant_id
    AND payload_json IS DISTINCT FROM '{"redacted": true}'::jsonb
    AND (
      aggregate_id = p_membership_id::text
      OR strpos(payload_json::text, p_membership_id::text) > 0
      OR (principal IS NOT NULL AND strpos(payload_json::text, principal::text) > 0)
      OR (principal_email IS NOT NULL AND strpos(lower(payload_json::text), principal_email) > 0)
    );
  GET DIAGNOSTICS redacted_events = ROW_COUNT;

  UPDATE public.member_erasures
  SET database_completed_at = now(),
      pending_objects = pending,
      outcome_json = jsonb_build_object(
        'deleted', deleted,
        'auditEntriesRedacted', redacted_audit,
        'eventsRedacted', redacted_events
      )
  WHERE id = erasure.id;

  UPDATE public.deletion_requests
  SET status = 'RUNNING', updated_at = now()
  WHERE id = p_deletion_request_id AND tenant_id = p_tenant_id;

  RETURN jsonb_build_object(
    'erasureId', erasure.id,
    'principalId', principal,
    'pendingObjects', pending,
    'alreadyErased', false
  );
END;
$$;

-- Deletes the erased member's global login account, unless another academy
-- still has a membership for it (the memberships foreign key refuses) or it is
-- a platform operator. Sessions, login methods and authenticators go with it
-- (ON DELETE CASCADE). Returns whether it was deleted.
CREATE OR REPLACE FUNCTION app.erase_member_account(p_erasure_id uuid)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public, app, pg_temp
AS $$
DECLARE
  principal uuid;
BEGIN
  SELECT me.principal_id INTO principal
  FROM public.member_erasures me
  WHERE me.id = p_erasure_id AND me.database_completed_at IS NOT NULL;
  IF principal IS NULL THEN
    RETURN false;
  END IF;
  IF EXISTS (SELECT 1 FROM public.platform_operators po WHERE po.auth_principal_id = principal) THEN
    RETURN false;
  END IF;
  IF EXISTS (SELECT 1 FROM public.memberships m WHERE m.auth_principal_id = principal) THEN
    RETURN false;
  END IF;
  DELETE FROM public.auth_principals WHERE id = principal;
  RETURN FOUND;
EXCEPTION
  -- Another academy's membership (seen by the foreign key, which no policy
  -- hides) or another reference keeps the account.
  WHEN foreign_key_violation THEN
    RETURN false;
END;
$$;

-- Finishes an erasure: records the outcome on the log and the request, and
-- marks the request SUCCEEDED. p_outcome is the versioned outcome
-- (privacy-lifecycle.contract.ts, version 2).
CREATE OR REPLACE FUNCTION app.complete_member_erasure(
  p_erasure_id uuid,
  p_remaining_objects jsonb,
  p_outcome jsonb
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public, app, pg_temp
AS $$
DECLARE
  erasure public.member_erasures%ROWTYPE;
BEGIN
  SELECT * INTO erasure FROM public.member_erasures
  WHERE id = p_erasure_id AND database_completed_at IS NOT NULL
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'erasure % has not erased its database records', p_erasure_id USING ERRCODE = 'P0002';
  END IF;

  UPDATE public.member_erasures
  SET pending_objects = coalesce(p_remaining_objects, '[]'::jsonb),
      completed_at = CASE WHEN jsonb_array_length(coalesce(p_remaining_objects, '[]'::jsonb)) = 0 THEN now() ELSE NULL END,
      outcome_json = coalesce(outcome_json, '{}'::jsonb) || jsonb_build_object('final', p_outcome)
  WHERE id = erasure.id;

  IF jsonb_array_length(coalesce(p_remaining_objects, '[]'::jsonb)) = 0 AND erasure.deletion_request_id IS NOT NULL THEN
    UPDATE public.deletion_requests
    SET status = 'SUCCEEDED', completed_at = now(), outcome_json = p_outcome, updated_at = now()
    WHERE id = erasure.deletion_request_id AND tenant_id = erasure.tenant_id;
  END IF;
END;
$$;

-- Owned by atlas_platform so they run with its privileges and policies. The
-- migration user may create functions in app; atlas_platform may not, and an
-- owner change needs the new owner to be able to, so it is allowed only for
-- the change.
GRANT CREATE ON SCHEMA app TO atlas_platform;
ALTER FUNCTION app.erase_member(uuid, uuid, uuid) OWNER TO atlas_platform;
ALTER FUNCTION app.erase_member_account(uuid) OWNER TO atlas_platform;
ALTER FUNCTION app.complete_member_erasure(uuid, jsonb, jsonb) OWNER TO atlas_platform;
REVOKE CREATE ON SCHEMA app FROM atlas_platform;

REVOKE ALL ON FUNCTION app.erase_member(uuid, uuid, uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION app.erase_member_account(uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION app.complete_member_erasure(uuid, jsonb, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION app.erase_member(uuid, uuid, uuid) TO atlas_app;
GRANT EXECUTE ON FUNCTION app.erase_member_account(uuid) TO atlas_app;
GRANT EXECUTE ON FUNCTION app.complete_member_erasure(uuid, jsonb, jsonb) TO atlas_app;
